import{_ as e,o as d,c as r,ag as n}from"./chunks/framework.CrXGS008.js";const b=JSON.parse('{"title":"Einstellungen","description":"","frontmatter":{},"headers":[],"relativePath":"de/car-wash/settings.md","filePath":"de/car-wash/settings.md"}'),a={name:"de/car-wash/settings.md"};function i(o,t,s,c,h,l){return d(),r("div",null,[...t[0]||(t[0]=[n('<h1 id="einstellungen" tabindex="-1">Einstellungen <a class="header-anchor" href="#einstellungen" aria-label="Permalink to &quot;Einstellungen&quot;">​</a></h1><p>Jede Car Wash Einstellung wird in <code>/nay</code> bearbeitet, auf der Seite <strong>Car Wash</strong> (Scope <code>nay_car_wash.config</code>). Änderungen werden in der Datenbank gespeichert und sofort für jeden Spieler übernommen. <code>config.lua</code> enthält optionale Startwerte: Sie gelten, bis eine Einstellung in <code>/nay</code> geändert wird, und <strong>Zurücksetzen</strong> kehrt zu ihnen zurück.</p><p>Die Spalte <strong>In /nay</strong> zeigt den Namen, der im Panel angezeigt wird. Der Schlüssel ist der Name, den <code>config.lua</code> und die <a href="/de/nay-lib/api">HTTP-API</a> verwenden.</p><h2 id="allgemein" tabindex="-1">Allgemein <a class="header-anchor" href="#allgemein" aria-label="Permalink to &quot;Allgemein&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Standard</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Aktiviert</td><td><code>Enabled</code></td><td>an / aus</td><td>an</td><td>Schaltet alle Waschstraßen und Hochdruckreiniger ein oder aus.</td></tr><tr><td>Interaktion zu Fuß</td><td><code>InteractionMode</code></td><td><code>key</code> oder <code>target</code></td><td><code>key</code></td><td>Wie Spieler einen Hochdruckreiniger starten: Tastenhinweis (E) oder Target-Auge. Waschstraßen nutzen immer E aus dem Fahrzeug.</td></tr><tr><td>Zahlungskonto</td><td><code>Account</code></td><td><code>cash</code>, <code>bank</code> oder <code>cash_then_bank</code></td><td><code>cash_then_bank</code></td><td>Von wo der Preis abgebucht wird. <code>cash_then_bank</code> nutzt die Bank, wenn das Bargeld nicht reicht.</td></tr><tr><td>Job-Rabatte</td><td><code>JobDiscounts</code></td><td>Liste, bis zu 32</td><td>keine</td><td>Rabatte für einen Job ab einem Rang, für Waschstraßen und Hochdruckreiniger.</td></tr></tbody></table><p>Einträge unter <strong>Job-Rabatte</strong>:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Job</td><td><code>Job</code></td><td>Text, 1 bis 32 Zeichen</td><td>Name des Jobs, wie in deinem Framework.</td></tr><tr><td>Mindestrang</td><td><code>MinGrade</code></td><td>Zahl, 0 bis 100</td><td>Niedrigster Rang, der den Rabatt bekommt.</td></tr><tr><td>Rabatt (%)</td><td><code>Percent</code></td><td>Zahl, 1 bis 100</td><td>Rabatt in Prozent. 100 macht die Wäsche kostenlos.</td></tr></tbody></table><h2 id="waschstraßen" tabindex="-1">Waschstraßen <a class="header-anchor" href="#waschstraßen" aria-label="Permalink to &quot;Waschstraßen&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Standard</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Waschprogramme</td><td><code>Programs</code></td><td>Liste, 1 bis 8</td><td>Express $150, Standard $250, Premium $400</td><td>Waschprogramme, die in jeder Waschstraße angeboten werden.</td></tr><tr><td>Waschstraßen</td><td><code>Tunnels</code></td><td>Liste, bis zu 32</td><td>Strawberry, Little Seoul</td><td>Die Waschstraßen. Platziert mit dem <a href="/de/car-wash/tunnels">Editor für Waschstraßen</a>.</td></tr><tr><td>Maximale Fahrzeugbreite (m)</td><td><code>MaxVehicleWidth</code></td><td>Meter, 1 bis 6</td><td>2,25</td><td>Breitere Fahrzeuge werden abgewiesen.</td></tr><tr><td>Gesperrte Fahrzeugklassen</td><td><code>BlockedClasses</code></td><td>Liste von Fahrzeugklassen</td><td>Motorräder, Fahrräder, Boote, Hubschrauber, Flugzeuge, Züge</td><td>Fahrzeugklassen, die an der Einfahrt abgewiesen werden.</td></tr><tr><td>Saubere Fahrzeuge ablehnen</td><td><code>RequireDirt</code></td><td>an / aus</td><td>aus</td><td>Weist Fahrzeuge ab, die bereits sauber sind.</td></tr><tr><td>IPL der Kartenwaschanlagen ersetzen</td><td><code>ReplaceMapIpls</code></td><td>an / aus</td><td>an</td><td>Ersetzt in Strawberry die Standard-Waschanlage durch ihre Variante ohne Bürsten. Schalte es aus, wenn eine eigene Map oder ein Mapping-Manager diese Waschanlage übernimmt.</td></tr></tbody></table><p>Einträge unter <strong>Waschprogramme</strong>:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Name</td><td><code>Label</code></td><td>Text, 1 bis 32 Zeichen</td><td>Name im Waschmenü.</td></tr><tr><td>Preis</td><td><code>Price</code></td><td>Zahl, 0 bis 1000000</td><td>Preis vor Rabatten und dem Prozentsatz der Waschstraße.</td></tr><tr><td>Tempo (%)</td><td><code>SpeedPercent</code></td><td>Zahl, 25 bis 300</td><td>Tempo im Verhältnis zum Tempo der Waschstraße.</td></tr><tr><td>Schaum</td><td><code>Soap</code></td><td>an / aus</td><td>Lässt den Schaumbogen laufen.</td></tr><tr><td>Spülen</td><td><code>Rinse</code></td><td>an / aus</td><td>Lässt den Spülbogen laufen.</td></tr><tr><td>Trocknen</td><td><code>Dry</code></td><td>an / aus</td><td>Lässt den Trockner laufen.</td></tr><tr><td>Wachs (Minuten)</td><td><code>WaxMinutes</code></td><td>Zahl, 0 bis 1440</td><td>Minuten, die das Fahrzeug nach der Wäsche sauber bleibt. 0 bedeutet kein Wachs.</td></tr></tbody></table><p>Einträge unter <strong>Waschstraßen</strong> bearbeitest du leichter mit dem <a href="/de/car-wash/tunnels">Editor für Waschstraßen</a>, der diese Felder für dich ausfüllt:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Name</td><td><code>Label</code></td><td>Text, bis zu 48 Zeichen</td><td>Titel des Waschmenüs, auch im Verlauf und in Webhooks verwendet. Optional.</td></tr><tr><td>Geöffnet</td><td><code>Enabled</code></td><td>an / aus</td><td>Schließt eine Waschstraße, ohne sie zu löschen.</td></tr><tr><td>Einfahrt</td><td><code>Entry</code></td><td>Position und Ausrichtung</td><td>Wo der Fahrer anhält und E drückt.</td></tr><tr><td>Linienanfang</td><td><code>Start</code></td><td>Position</td><td>Anfang der Linie, der das Fahrzeug folgt.</td></tr><tr><td>Linienende</td><td><code>Finish</code></td><td>Position</td><td>Ende der Linie.</td></tr><tr><td>Breite (m)</td><td><code>Width</code></td><td>Meter, 2 bis 10</td><td>Spurbreite: bestimmt die Größe der Bögen, begrenzt die Fahrzeugbreite (0,5 m Spielraum) und wird für die Prüfung auf blockierte Spur genutzt.</td></tr><tr><td>Tempo (m/s)</td><td><code>Speed</code></td><td>Meter pro Sekunde, 0,5 bis 8</td><td>Grundtempo durch die Waschstraße, multipliziert mit dem Tempo des Programms.</td></tr><tr><td>Preis (%)</td><td><code>PricePercent</code></td><td>Zahl, 0 bis 1000</td><td>Prozentsatz, der in dieser Waschstraße auf jeden Programmpreis angewendet wird. 100 behält die Preise bei.</td></tr><tr><td>Schaumbogen</td><td><code>SoapJet</code></td><td>Position</td><td>Schaumbogen.</td></tr><tr><td>Dachbürste</td><td><code>HorizontalRoller</code></td><td>Position</td><td>Obere Bürste.</td></tr><tr><td>Seitenbürsten</td><td><code>VerticalRoller</code></td><td>Position</td><td>Seitliche Bürsten.</td></tr><tr><td>Spülbogen</td><td><code>RinseJet</code></td><td>Position</td><td>Spülbogen.</td></tr><tr><td>Trockner</td><td><code>Dryer</code></td><td>Position</td><td>Dampftrockner. Optional.</td></tr></tbody></table><p>Einträge unter <strong>Gesperrte Fahrzeugklassen</strong> haben ein einziges Feld, <strong>Klasse</strong> (<code>Class</code>), ausgewählt aus den GTA-Fahrzeugklassen nach Name.</p><h2 id="hochdruckreiniger" tabindex="-1">Hochdruckreiniger <a class="header-anchor" href="#hochdruckreiniger" aria-label="Permalink to &quot;Hochdruckreiniger&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Standard</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Hochdruckreiniger</td><td><code>ManualEnabled</code></td><td>an / aus</td><td>an</td><td>Schaltet die Hochdruckreiniger ein oder aus.</td></tr><tr><td>Props der Hochdruckreiniger</td><td><code>ManualModels</code></td><td>Liste, bis zu 16</td><td><code>prop_gas_airunit01</code></td><td>Welt-Props, die zu Hochdruckreinigern werden, überall wo die Karte sie hat.</td></tr><tr><td>Platzierte Hochdruckreiniger</td><td><code>ManualStations</code></td><td>Liste, bis zu 64</td><td>keine</td><td>Hochdruckreiniger, die du selbst platzierst.</td></tr><tr><td>Preis pro Schmutzstufe</td><td><code>ManualPricePerLevel</code></td><td>Zahl, 0 bis 100000</td><td>15</td><td>Preis einer Schmutzstufe, vor Job-Rabatten.</td></tr><tr><td>Sekunden pro Schmutzstufe</td><td><code>ManualSecondsPerLevel</code></td><td>Sekunden, 0,2 bis 10</td><td>1</td><td>Zeit, um eine Schmutzstufe zu reinigen.</td></tr></tbody></table><p>Einträge unter <strong>Props der Hochdruckreiniger</strong> haben ein einziges Feld, <strong>Modellname</strong> (<code>Model</code>): der Modellname des Props (Buchstaben, Ziffern und Unterstriche).</p><p>Einträge unter <strong>Platzierte Hochdruckreiniger</strong>:</p><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Name</td><td><code>Label</code></td><td>Text, bis zu 48 Zeichen</td><td>Name der Station, im Verlauf und in Webhooks verwendet. Optional.</td></tr><tr><td>Position</td><td><code>Coords</code></td><td>Position und Ausrichtung</td><td>Wo sie steht. <strong>Meine Position verwenden</strong> füllt sie mit deinem aktuellen Standort aus.</td></tr></tbody></table><p>Mehr dazu auf der Seite <a href="/de/car-wash/pressure-washers">Hochdruckreiniger</a>.</p><h2 id="blips" tabindex="-1">Blips <a class="header-anchor" href="#blips" aria-label="Permalink to &quot;Blips&quot;">​</a></h2><table tabindex="0"><thead><tr><th>In /nay</th><th>Schlüssel</th><th>Typ</th><th>Standard</th><th>Beschreibung</th></tr></thead><tbody><tr><td>Blips anzeigen</td><td><code>ShowBlips</code></td><td>an / aus</td><td>an</td><td>Zeigt die Waschstraßen und, solange die Hochdruckreiniger an sind, die platzierten Stationen auf der Karte.</td></tr><tr><td>Blip-Symbol</td><td><code>BlipSprite</code></td><td>Blip-Symbol</td><td>100</td><td>Ausgewählt aus einer visuellen Liste von Symbolen. Für einen eigenen Blip kann weiterhin jede Nummer eingegeben werden.</td></tr><tr><td>Blip-Farbe</td><td><code>BlipColor</code></td><td>Blip-Farbe</td><td>63</td><td>Ausgewählt aus einer visuellen Liste von Farben.</td></tr><tr><td>Blip-Größe</td><td><code>BlipScale</code></td><td>0,2 bis 2</td><td>0,8</td><td>Größe des Blips.</td></tr></tbody></table>',22)])])}const g=e(a,[["render",i]]);export{b as __pageData,g as default};
